CREATE TABLE appointments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, location VARCHAR(255) NULL, status ENUM('scheduled','completed','cancelled') NOT NULL DEFAULT 'scheduled', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_appointments_owner_starts (owner_user_id,starts_at), CONSTRAINT chk_appointments_dates CHECK (ends_at > starts_at), CONSTRAINT fk_appointments_owner FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
